class Solution:
    def canVisitAllRooms(self, rooms: List[List[int]]) -> bool:
        visited = set([0])
        stack = [0]
        while stack:
            room = stack.pop()
            for key in rooms[room]:
                if key not in visited:
                    visited.add(key)
                    stack.append(key)
        return len(visited) == len(rooms)

class Solution:
    def splitIntoFibonacci(self, num: str) -> List[int]:
        def backtrack(idx, seq):
            if idx == len(num) and len(seq) >= 3:
                return True
            for i in range(idx, len(num)):
                if num[idx] == '0' and i > idx:
                    break
                val = int(num[idx:i+1])
                if val > 2**31 - 1:
                    break
                if len(seq) >= 2 and val > seq[-1] + seq[-2]:
                    break
                if len(seq) < 2 or val == seq[-1] + seq[-2]:
                    seq.append(val)
                    if backtrack(i+1, seq):
                        return True
                    seq.pop()
            return False
        res = []
        backtrack(0, res)
        return res

