class Solution:
    def backspaceCompare(self, s: str, t: str) -> bool:
        def get_next(s, i):
            skip = 0
            while i >= 0:
                if s[i] == '#':
                    skip += 1
                elif skip > 0:
                    skip -= 1
                else:
                    break
                i -= 1
            return i
        i, j = len(s)-1, len(t)-1
        while i >= 0 or j >= 0:
            i, j = get_next(s, i), get_next(t, j)
            if i >= 0 and j >= 0 and s[i] != t[j]:
                return False
            if (i >= 0) != (j >= 0):
                return False
            i -= 1
            j -= 1
        return True

class Solution:
    def longestMountain(self, arr: List[int]) -> int:
        n, res = len(arr), 0
        i = 1
        while i < n - 1:
            if arr[i-1] < arr[i] > arr[i+1]:
                l, r = i-1, i+1
                while l > 0 and arr[l-1] < arr[l]: l -= 1
