class Solution:
    def rectangleArea(self, rectangles: List[List[int]]) -> int:
        MOD = 10**9 + 7
        xs = sorted(set(x for r in rectangles for x in [r[0], r[2]]))
        x_idx = {x: i for i, x in enumerate(xs)}
        events = []
        for x1, y1, x2, y2 in rectangles:
            events.append((y1, 0, x1, x2))
            events.append((y2, 1, x1, x2))
        events.sort()
        count = [0] * len(xs)
        ans, prev_y = 0, events[0][0]
        for y, typ, x1, x2 in events:
            width = sum(xs[i+1] - xs[i] for i in range(len(xs)-1) if count[i] > 0)
            ans += width * (y - prev_y)
            prev_y = y
            for i in range(x_idx[x1], x_idx[x2]):
                count[i] += 1 if typ == 0 else -1
        return ans % MOD

