class Solution:
    def kSimilarity(self, s1: str, s2: str) -> int:
        from collections import deque
        if s1 == s2: return 0
        queue = deque([(s1, 0)])
        visited = {s1}
        while queue:
            curr, swaps = queue.popleft()
            i = 0
            while curr[i] == s2[i]: i += 1
            for j in range(i+1, len(curr)):
                if curr[j] == s2[i] and curr[j] != s2[j]:
                    nxt = list(curr)
                    nxt[i], nxt[j] = nxt[j], nxt[i]
                    nxt = ''.join(nxt)
