    def distanceK(self, root: TreeNode, target: TreeNode, k: int) -> List[int]:
        import collections
        parent = {}
        def dfs(node, par):
            if node:
                parent[node] = par
                dfs(node.left, node)
                dfs(node.right, node)
        dfs(root, None)
        queue = collections.deque([(target, 0)])
        visited = {target}
        res = []
        while queue:
            node, dist = queue.popleft()
